    (tsb, sz) <- EVAL(A)
    pred <- 2^sz - 1
    assert tsb <= pred            # Corollary 4.9
    return (tsb, pred)

function EVAL(A):                 # post-order, returns (typeStateBound, size)
    if A = base:
        return (1, 1)
    else A = arrow(L, R):
        (tl, sl) <- EVAL(L)
        (tr, sr) <- EVAL(R)
        tsb <- (tl + 1) * (tr + 1)
        sz  <- 1 + sl + sr
        return (tsb, sz)

